    job_id TEXT NOT NULL REFERENCES v3_jobs(job_id) ON DELETE CASCADE,
    version_id TEXT NOT NULL REFERENCES rw_versions(version_id) ON DELETE CASCADE,
    interview_id TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,
    PRIMARY KEY(job_id,version_id,interview_id));
CREATE TABLE v3_jobs (
    job_id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,request_key TEXT NOT NULL,
    request_hash TEXT NOT NULL,payload TEXT NOT NULL,stage TEXT NOT NULL,
    revision INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
    UNIQUE(owner_id,request_key));
CREATE TABLE v3_project_files (
    snapshot_id TEXT NOT NULL REFERENCES v3_project_snapshots(snapshot_id) ON DELETE CASCADE,
    path TEXT NOT NULL,content_hash TEXT NOT NULL,text TEXT NOT NULL,
    PRIMARY KEY(snapshot_id,path));
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','README.md','81ea4e8f6d9b417d4d0718d253f2dacbd027a5af1af985018bfc383e24289bce','# Lease fixture
This fixture checks a token and an expiry time before returning an artifact.
It does not connect to a database or publish messages.
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','docs/visibility.md','d233fa634b7547b88f43f992c339171d82bbed3fbb901b0977e0e0bbd26174c9','# Visibility teaching fixture
## Trust
The allowed IDs come from a trusted server session. User query text is not a permission filter.
## Retention
A deletion marker hides a record; it does not prove physical erasure of archived records.
## Evidence
This fixture has no database connection and no execution logs.
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','events.py','87924a87d35a7772cf8f273df7fd2d288f0283341dff8bb7fb1687d09562cf04','def append_event(events, event_id, payload):
    if event_id in events:
        return events[event_id]
    events[event_id] = payload
    return payload
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','filters.py','99b69137e0ac702b0899c84ba8d60a223080d97b95f6d71bdb1410dd32a164e3','def bounded_records(records, allowed_ids, limit):
    allowed = [row for row in records if row["id"] in allowed_ids]
    return allowed[:limit]

def visible(row, owner):
    return row["owner"] == owner and not row.get("deleted", False)
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','lease.py','1076ce2d2095cfd560ab96c11a592514340031ac9c931b6550a8e7eade8dc34a','def can_publish(current_token, attempt_token, lease_until, now):
    return current_token == attempt_token and lease_until > now
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','publish.py','53812a9e6e5bad29081274a83044c8ee8542e42df1e41734e73da64d46dd77cd','from lease import can_publish

def publish(current, attempt, expires, now, artifact):
    if not can_publish(current, attempt, expires, now):
        raise ValueError("lease_lost")
    return artifact
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','tests/test_filters.py','dd294afc08b33fda099ca90352860b2413303cbc4387bd7e778ea35407dae381','from filters import bounded_records, visible

def test_filter_before_limit():
    rows = [{"id": "outside"}, {"id": "inside"}]
    assert bounded_records(rows, {"inside"}, 1) == [{"id": "inside"}]

def test_deleted_row():
    assert not visible({"owner": "alice", "deleted": True}, "alice")
');
INSERT INTO "v3_project_files" VALUES('snapshot-bb67c8671f304921b9f099495b1a9b64','tests/test_lease.py','cee767aa87580bf7f5b0c51304930ab881992935472f0dfb4df296fc2002b755','from lease import can_publish

def test_old_token():
    assert not can_publish("new", "old", 100, 1)

def test_expired():
    assert not can_publish("same", "same", 1, 2)
');
