INSERT INTO "v3_public_versions" VALUES('knowledge-a253bcbd641cf83ac83b2f6dccffb9ba7786644478328ad7e0bb43de83e35687','doc-asyncio','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"仅调用async函数会得到协程对象，不会自动执行；需要await或调度Task。协程适合可等待的IO任务。同步阻塞库直接运行在事件循环里会拖住其他任务，可考虑受限线程；CPU密集计算应根据运行环境另选进程等方案。取消请求也需要处理清理工作，不能把客户端超时理解为远端副作用已撤销。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-asyncio","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://docs.python.org/3.12/library/asyncio-task.html","source_version":"Python 3.12 documentation","tags":["asyncio","Python","协程","并发","阻塞"],"technical_doc_id":null,"title":"协作式并发与阻塞边界","updated_at":"2026-10-20"}','a253bcbd641cf83ac83b2f6dccffb9ba7786644478328ad7e0bb43de83e35687','f85f73cf3762d49bae54a9289f28e26aefd6508b16e384bce404a32fb2e3ed83');
INSERT INTO "v3_public_versions" VALUES('knowledge-0ca26e3a69d76e3ad44018cf31eaa7662e035e2a2934f7e0193f417a923b467b','doc-schema','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"Pydantic模型约束请求字段、类型和取值，FastAPI据此解析请求体。字段结构正确不代表业务事实正确；还需验证owner、版本、引用原文和状态迁移。模型输出同样要做Schema与业务两层校验，修复与重试都应有限。简历中数字、职责和来源是否支持，需要额外审查，不能由JSON格式成功推出。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-schema","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://fastapi.tiangolo.com/tutorial/body/","source_version":"FastAPI rolling tutorial; checked 2026-10-20","tags":["Pydantic","schema","JSON","校验","结构化"],"technical_doc_id":null,"title":"结构化输出与业务校验","updated_at":"2026-10-20"}','0ca26e3a69d76e3ad44018cf31eaa7662e035e2a2934f7e0193f417a923b467b','1c595ed37e94198f93766b35c18a98cb70cccc6457b6f03b5d40b2b9a8be92da');
INSERT INTO "v3_public_versions" VALUES('knowledge-90e4ab55ba319ad62c0ab381f1c54f0ada352f66fb587e5d2b19492fa701e758','doc-transaction','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"事务把一组数据库修改作为整体提交或回滚。任务记录与待投递消息可以在同一数据库事务内落盘，再由发布者发送消息；这就是项目旧后端Outbox路径的设计。发布者中断或确认丢失仍可能造成重复投递，消费者必须依据持久任务状态和操作键去重。本地数据库事务不能直接保证外部消息系统与副作用恰好一次。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-transaction","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://www.postgresql.org/docs/14/tutorial-transactions.html","source_version":"PostgreSQL 14 tutorial","tags":["PostgreSQL","事务","Outbox","原子","transaction"],"technical_doc_id":null,"title":"业务事务与消息投递","updated_at":"2026-10-20"}','90e4ab55ba319ad62c0ab381f1c54f0ada352f66fb587e5d2b19492fa701e758','ffb211ced90e3abb9cfd4bfc9664aabf547ec40422a9658516b8e96021459c6a');
INSERT INTO "v3_public_versions" VALUES('knowledge-a79fedf0639d23bed4d9c86bfdd20419a01c397fe9e487f08874045014dac936','doc-tree-sitter','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"Tree-sitter的语言语法和解析器可构建语法树，定位JS、TS及TSX中的声明。解析成功不等于类型检查或程序运行成功。本项目提取函数、方法和导入引用，遇到语法错误或插件缺失会明确降级为文本，不构造猜测的关系。引用仍依赖快照、文件哈希与行原文校验。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-tree-sitter","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://tree-sitter.github.io/py-tree-sitter/","source_version":"py-tree-sitter 0.26 documentation","tags":["Tree-sitter","TypeScript","JavaScript","TSX","解析"],"technical_doc_id":null,"title":"JS/TS语法解析与降级","updated_at":"2026-10-20"}','a79fedf0639d23bed4d9c86bfdd20419a01c397fe9e487f08874045014dac936','49e7d90847695775e0e8673403a2f21c6522b810c9f2f3c7f71d70594f985561');
